// src/components/CorpusManager.jsx
import { useState, useEffect, useRef, useCallback } from "react";
import { api } from "../api/client";

const LANG_OPTIONS     = ["en","hi","ta","fr","de","es","zh","ar"];
const MODALITY_ICON    = { text: "📄", image: "🖼️", audio: "🎵" };
const ACCEPT_BY_MOD    = {
  text:  ".txt,.md,.pdf,.docx,.html,.csv,.json",
  image: ".jpg,.jpeg,.png,.webp,.gif,.bmp",
  audio: ".mp3,.wav,.m4a,.ogg,.flac,.aac",
  any:   ".txt,.md,.pdf,.docx,.html,.csv,.json,.jpg,.jpeg,.png,.webp,.gif,.bmp,.mp3,.wav,.m4a,.ogg,.flac,.aac",
};

function isBinary(content) {
  return typeof content === "string" && content.startsWith("b'\\x");
}

function safeContent(doc) {
  if (doc.modality === "image" || doc.modality === "audio") return null;
  if (isBinary(doc.content)) return null;
  return String(doc.content ?? "").slice(0, 140);
}

// Group docs by source so the list is readable
function groupBySource(docs) {
  const map = new Map();
  docs.forEach(doc => {
    const key = doc.source || "unknown";
    if (!map.has(key)) map.set(key, { source: key, modality: doc.modality, lang: doc.lang,
      provenance_score: doc.provenance_score, filepath: doc.filepath || "", chunks: [] });
    map.get(key).chunks.push(doc);
  });
  return [...map.values()];
}

export default function CorpusManager({ onClose, onCorpusChange }) {
  const [docs,      setDocs]      = useState([]);
  const [groups,    setGroups]    = useState([]);
  const [loading,   setLoading]   = useState(true);
  const [error,     setError]     = useState(null);
  const [success,   setSuccess]   = useState(null);
  const [tab,       setTab]       = useState("browse");  // "browse" | "add-text" | "upload"
  const [deleting,  setDeleting]  = useState(new Set());
  const [rebuilding,setRebuilding]= useState(false);

  // Text-add form
  const [textForm,  setTextForm]  = useState({
    content: "", source: "", lang: "en", provenance_score: 0.85
  });
  const [adding,    setAdding]    = useState(false);

  // File upload form
  const [uploads,   setUploads]   = useState([]);   // [{file, source, lang, prov, status}]
  const [uploading, setUploading] = useState(false);
  const fileInputRef = useRef();

  const flash = (msg, isErr=false) => {
    isErr ? setError(msg) : setSuccess(msg);
    setTimeout(() => isErr ? setError(null) : setSuccess(null), 4000);
  };

  const fetchCorpus = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await api.getCorpus();
      const docList = data.documents || [];
      setDocs(docList);
      setGroups(groupBySource(docList));
    } catch (e) { flash(e.message, true); }
    finally { setLoading(false); }
  }, []);

  useEffect(() => { fetchCorpus(); }, [fetchCorpus]);

  // ── Delete by source (removes all chunks of that file) ──────────────
  async function handleDeleteSource(source) {
    setDeleting(d => new Set(d).add(source));
    try {
      await api.removeBySource(source);
      flash(`Deleted "${source}" and rebuilt index.`);
      await fetchCorpus();
      onCorpusChange();
    } catch (e) { flash(e.message, true); }
    finally { setDeleting(d => { const s = new Set(d); s.delete(source); return s; }); }
  }

  // ── Manual rebuild ────────────────────────────────────────────────────
  async function handleRebuild() {
    setRebuilding(true);
    try {
      const r = await api.rebuildIndex();
      flash(`Index rebuilt — ${r.vectors} vectors.`);
    } catch (e) { flash(e.message, true); }
    finally { setRebuilding(false); }
  }

  // ── Reset to demo corpus ──────────────────────────────────────────────
  async function handleReset() {
    try {
      await api.resetCorpus();
      await fetchCorpus();
      onCorpusChange();
      flash("Demo corpus loaded.");
    } catch (e) { flash(e.message, true); }
  }

  // ── Add text document ─────────────────────────────────────────────────
  async function handleAddText(e) {
    e.preventDefault();
    if (!textForm.content.trim()) return;
    setAdding(true);
    try {
      await api.addDocument({ ...textForm, modality: "text" });
      await fetchCorpus();
      onCorpusChange();
      setTextForm({ content: "", source: "", lang: "en", provenance_score: 0.85 });
      flash("Document added and indexed.");
    } catch (e) { flash(e.message, true); }
    finally { setAdding(false); }
  }

  // ── File upload queue ─────────────────────────────────────────────────
  function handleFilePick(e) {
    const files = [...e.target.files];
    const newItems = files.map(f => ({
      file: f,
      source: f.name.replace(/\.[^/.]+$/, ""),
      lang: "en",
      prov: 0.85,
      status: "pending",   // pending | uploading | done | error
      error: "",
    }));
    setUploads(prev => [...prev, ...newItems]);
    e.target.value = "";
  }

  function removeFromQueue(idx) {
    setUploads(prev => prev.filter((_, i) => i !== idx));
  }

  async function handleUploadAll() {
    if (uploading) return;
    setUploading(true);
    let anyDone = false;
    for (let i = 0; i < uploads.length; i++) {
      const item = uploads[i];
      if (item.status === "done") continue;
      setUploads(prev => prev.map((u, j) => j === i ? { ...u, status: "uploading" } : u));
      try {
        const fd = new FormData();
        fd.append("file", item.file);
        fd.append("source", item.source);
        fd.append("lang", item.lang);
        fd.append("provenance_score", String(item.prov));
        await api.uploadFile(fd);
        setUploads(prev => prev.map((u, j) => j === i ? { ...u, status: "done" } : u));
        anyDone = true;
      } catch (err) {
        setUploads(prev => prev.map((u, j) =>
          j === i ? { ...u, status: "error", error: err.message } : u));
      }
    }
    setUploading(false);
    if (anyDone) {
      await fetchCorpus();
      onCorpusChange();
      flash("Files uploaded and indexed.");
    }
  }

  // ── Modality badge colour ─────────────────────────────────────────────
  const modClass = m => m === "image" ? "doc-tag-image" : m === "audio" ? "doc-tag-audio" : "";

  // ── Stats bar ─────────────────────────────────────────────────────────
  const byMod = docs.reduce((acc, d) => {
    acc[d.modality] = (acc[d.modality] || 0) + 1; return acc;
  }, {});

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal cm-modal" onClick={e => e.stopPropagation()}>

        {/* Header */}
        <div className="modal-header">
          <span className="modal-title">Corpus Manager</span>
          <span className="modal-badge">{groups.length} sources · {docs.length} chunks</span>
          <div className="cm-stat-pills">
            {Object.entries(byMod).map(([m, n]) => (
              <span key={m} className={`cm-stat-pill ${modClass(m)}`}>
                {MODALITY_ICON[m]} {n}
              </span>
            ))}
          </div>
          <button className="modal-close" onClick={onClose}>✕</button>
        </div>

        {/* Flash messages */}
        {error   && <div className="modal-error">⚠ {error}</div>}
        {success && <div className="modal-success">✓ {success}</div>}

        {/* Tab bar */}
        <div className="cm-tabs">
          {[["browse","Browse Corpus"],["add-text","Add Text"],["upload","Upload Files"]].map(
            ([key, label]) => (
              <button key={key}
                className={`cm-tab ${tab === key ? "cm-tab-active" : ""}`}
                onClick={() => setTab(key)}>
                {label}
              </button>
            )
          )}
        </div>

        {/* ── Tab: Browse ── */}
        {tab === "browse" && (
          <div className="cm-body">
            {loading ? (
              <div className="modal-empty"><span className="spinner" /> Loading…</div>
            ) : groups.length === 0 ? (
              <div className="modal-empty">No documents yet. Upload files or add text.</div>
            ) : (
              groups.map(g => (
                <div className="cm-group" key={g.source}>
                  <div className="cm-group-header">
                    <span className={`doc-tag ${modClass(g.modality)}`}>
                      {MODALITY_ICON[g.modality] || "📄"} {g.modality}
                    </span>
                    <span className="doc-tag doc-tag-lang">{g.lang}</span>
                    <span className="cm-source-name">{g.source}</span>
                    <span className="cm-chunk-count">{g.chunks.length} chunk{g.chunks.length !== 1 ? "s" : ""}</span>
                    {g.filepath && (
                      <span className="cm-filepath" title={g.filepath}>
                        {g.filepath.split(/[\\/]/).pop()}
                      </span>
                    )}
                    <span className="cm-prov">prov {g.provenance_score?.toFixed(2)}</span>
                    <button
                      className="cm-delete-btn"
                      onClick={() => handleDeleteSource(g.source)}
                      disabled={deleting.has(g.source)}
                      title={`Delete all ${g.chunks.length} chunk(s) from "${g.source}"`}>
                      {deleting.has(g.source)
                        ? <span className="spinner-sm" />
                        : "🗑 Delete"}
                    </button>
                  </div>
                  {/* Preview first chunk if text */}
                  {g.chunks[0] && safeContent(g.chunks[0]) && (
                    <div className="cm-preview">
                      {safeContent(g.chunks[0])}
                      {g.chunks.length > 1 && (
                        <span className="cm-more"> …+{g.chunks.length - 1} more chunks</span>
                      )}
                    </div>
                  )}
                  {g.modality !== "text" && (
                    <div className="cm-preview cm-preview-binary">
                      {MODALITY_ICON[g.modality]} Binary file — stored at{" "}
                      {g.filepath || "(embedded)"}
                    </div>
                  )}
                </div>
              ))
            )}
          </div>
        )}

        {/* ── Tab: Add Text ── */}
        {tab === "add-text" && (
          <div className="cm-body">
            <form onSubmit={handleAddText} className="cm-form">
              <label className="cm-field-label">Content</label>
              <textarea
                className="form-textarea cm-textarea"
                rows={6}
                placeholder="Paste document text here…"
                value={textForm.content}
                onChange={e => setTextForm(f => ({ ...f, content: e.target.value }))}
              />
              <div className="cm-field-row">
                <div className="cm-field">
                  <label className="cm-field-label">Source name</label>
                  <input className="form-input"
                    placeholder="e.g. dgca_report_2023"
                    value={textForm.source}
                    onChange={e => setTextForm(f => ({ ...f, source: e.target.value }))} />
                </div>
                <div className="cm-field cm-field-sm">
                  <label className="cm-field-label">Language</label>
                  <select className="form-select"
                    value={textForm.lang}
                    onChange={e => setTextForm(f => ({ ...f, lang: e.target.value }))}>
                    {LANG_OPTIONS.map(l => <option key={l}>{l}</option>)}
                  </select>
                </div>
                <div className="cm-field cm-field-sm">
                  <label className="cm-field-label">Provenance</label>
                  <input className="form-input" type="number"
                    step="0.05" min="0" max="1"
                    value={textForm.provenance_score}
                    onChange={e => setTextForm(f => ({ ...f, provenance_score: parseFloat(e.target.value) }))} />
                </div>
              </div>
              <button className="cm-submit-btn" type="submit" disabled={adding || !textForm.content.trim()}>
                {adding ? <><span className="spinner-sm" /> Embedding…</> : "+ Add & Index"}
              </button>
            </form>
          </div>
        )}

        {/* ── Tab: Upload Files ── */}
        {tab === "upload" && (
          <div className="cm-body">
            {/* Drop zone */}
            <div
              className="cm-dropzone"
              onClick={() => fileInputRef.current?.click()}
              onDragOver={e => { e.preventDefault(); e.currentTarget.classList.add("cm-dropzone-over"); }}
              onDragLeave={e => e.currentTarget.classList.remove("cm-dropzone-over")}
              onDrop={e => {
                e.preventDefault();
                e.currentTarget.classList.remove("cm-dropzone-over");
                const files = [...e.dataTransfer.files];
                const items = files.map(f => ({
                  file: f, source: f.name.replace(/\.[^/.]+$/, ""),
                  lang: "en", prov: 0.85, status: "pending", error: ""
                }));
                setUploads(prev => [...prev, ...items]);
              }}>
              <input ref={fileInputRef} type="file" multiple
                accept={ACCEPT_BY_MOD.any} style={{ display: "none" }}
                onChange={handleFilePick} />
              <div className="cm-dropzone-icon">⬆</div>
              <div className="cm-dropzone-text">
                Click or drag &amp; drop files here
              </div>
              <div className="cm-dropzone-hint">
                Text: PDF, DOCX, TXT, MD, HTML, CSV, JSON<br/>
                Image: JPG, PNG, WEBP, GIF, BMP<br/>
                Audio: MP3, WAV, M4A, OGG, FLAC
              </div>
            </div>

            {/* Upload queue */}
            {uploads.length > 0 && (
              <>
                <div className="cm-queue-header">
                  <span className="cm-field-label">{uploads.length} file(s) queued</span>
                  <button className="cm-clear-btn"
                    onClick={() => setUploads([])}
                    disabled={uploading}>
                    Clear all
                  </button>
                </div>
                <div className="cm-queue">
                  {uploads.map((item, i) => (
                    <div key={i} className={`cm-queue-row cm-queue-${item.status}`}>
                      <span className="cm-queue-icon">
                        {item.status === "done"      ? "✓" :
                         item.status === "error"     ? "✕" :
                         item.status === "uploading" ? <span className="spinner-sm"/> : "○"}
                      </span>
                      <span className="cm-queue-name" title={item.file.name}>
                        {item.file.name.length > 28
                          ? item.file.name.slice(0,25) + "…"
                          : item.file.name}
                      </span>
                      <span className="cm-queue-size">
                        {(item.file.size / 1024).toFixed(0)} KB
                      </span>
                      <input
                        className="form-input cm-queue-source"
                        placeholder="source name"
                        value={item.source}
                        disabled={item.status !== "pending"}
                        onChange={e => setUploads(prev =>
                          prev.map((u, j) => j === i ? { ...u, source: e.target.value } : u))}
                      />
                      <select className="form-select cm-queue-lang"
                        value={item.lang}
                        disabled={item.status !== "pending"}
                        onChange={e => setUploads(prev =>
                          prev.map((u, j) => j === i ? { ...u, lang: e.target.value } : u))}>
                        {LANG_OPTIONS.map(l => <option key={l}>{l}</option>)}
                      </select>
                      {item.status === "error" && (
                        <span className="cm-queue-error" title={item.error}>⚠ {item.error.slice(0,40)}</span>
                      )}
                      {item.status === "pending" && (
                        <button className="cm-queue-remove" onClick={() => removeFromQueue(i)}>✕</button>
                      )}
                    </div>
                  ))}
                </div>
                <button
                  className="cm-submit-btn"
                  onClick={handleUploadAll}
                  disabled={uploading || uploads.every(u => u.status === "done")}>
                  {uploading
                    ? <><span className="spinner-sm"/> Uploading…</>
                    : `⬆ Upload ${uploads.filter(u => u.status === "pending").length} file(s) & Index`}
                </button>
              </>
            )}
          </div>
        )}

        {/* Footer */}
        <div className="modal-footer cm-footer">
          <button className="btn-reset" onClick={handleReset}>↺ Load Demo Corpus</button>
          <button className="btn-reset cm-rebuild-btn" onClick={handleRebuild} disabled={rebuilding}>
            {rebuilding ? <><span className="spinner-sm"/> Rebuilding…</> : "⟳ Rebuild Index"}
          </button>
        </div>
      </div>
    </div>
  );
}
